function showStatus(s){status.textContent=s}
async function api(path,body){const r=await fetch('/api/reports/'+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});let d;try{d=await r.json()}catch{throw Error('The report service is unavailable. Please try again later.')}if(!r.ok)throw Error(d.error||'Report request failed.');return d}

let fxData=null,fxPending=null,fxVersion=0;
async function rates(){
 if(fxData&&Date.now()-fxData.loadedAt<86400000)return fxData;
 if(fxPending)return fxPending;
 fxPending=(async()=>{const r=await fetch('https://open.er-api.com/v6/latest/USD',{signal:AbortSignal.timeout(12000)}),d=await r.json();if(!r.ok||d.result!=='success'||d.base_code!=='USD'||!d.rates)throw Error('Exchange rates unavailable');fxData={...d,loadedAt:Date.now()};return fxData})().finally(()=>{fxPending=null});return fxPending;
}
function defaultBillingCountry(){const select=form.elements.billingCountry;for(const id of ['analysisCountry','hydroCountry','addressCountry']){const el=document.getElementById(id);if(!el?.value)continue;const label=el.selectedOptions?.[0]?.textContent?.trim();const option=[...select.options].find(o=>o.value===el.value||o.textContent===label||o.textContent===el.value);if(option){select.value=option.value;return}}select.value='SZ'}
async function updateLocalPrice(){const token=++fxVersion,price=dialog.querySelector('#rdLocalPrice'),note=dialog.querySelector('#rdRateNote');price.textContent='';note.textContent='';if(!config||!current||(!['catchment','wetlands'].includes(current?.service)&&window.SiegeUsage?.active?.policyVersion===1))return;const currency=form.elements.billingCountry.selectedOptions[0].dataset.currency,amount=config.prices[current.service]/100;if(config.currency!=='USD'){note.textContent='Local conversion is available for USD fees only.';return}if(currency==='USD'){price.textContent='USD '+amount.toFixed(2);return}price.textContent='Converting to '+currency+'…';try{const d=await rates();if(token!==fxVersion)return;const rate=d.rates[currency];if(!Number.isFinite(rate)||rate<=0)throw Error('Currency unavailable');price.textContent='≈ '+new Intl.NumberFormat(undefined,{style:'currency',currency,currencyDisplay:'code',minimumFractionDigits:2,maximumFractionDigits:2}).format(amount*rate);if(['fields','eco','hydrology','catchment','wetlands'].includes(current.service)){dialog.querySelector('#rdPrice').textContent=price.textContent;price.textContent='Charged in USD: '+amount.toFixed(2);}note.textContent='1 USD = '+rate.toFixed(4)+' '+currency+' · Rate date: '+new Date(d.time_last_update_unix*1000).toISOString().slice(0,10)}catch{if(token!==fxVersion)return;price.textContent='Local conversion unavailable';note.textContent='The USD fee remains valid. Try selecting the country again.'}}

function update(){const purchased=!['catchment','wetlands'].includes(current?.service)&&window.SiegeUsage?.active?.policyVersion===1?window.SiegeUsage.active:null;let card=form.elements.delivery.value==='card';if(purchased&&!['catchment','wetlands'].includes(current?.service)){card=purchased.method==='card';form.elements.delivery.value=purchased.method;form.querySelectorAll('[name=delivery]').forEach(x=>x.disabled=true);}submit.textContent=card?'Continue to secure Visa payment':'Request collection · pay cash';submit.disabled=busy||completed||!config||(!purchased&&(card?!config.cardEnabled:!config.collectionEnabled));dialog.querySelector('#rdAvailability').textContent=purchased?'Report delivery is included in this authorised AOI request. No second payment is required.':'Flat fee for the whole analysed area in this request, not per hectare. '+(card?(config?.cardEnabled?'Card details are entered only on the payment provider’s secure page. Your report is emailed after payment verification.':'Online payment is not configured. No analysis will start and no payment will be taken. Contact support@sieg.ltd.'):(config?.emailEnabled?(current?.kind==='download'?'Collection: Mzimnene complex, Manzini. Pay cash before collecting your digital files.':'Collection: Mzimnene complex, Manzini. SIEG will confirm when printing is complete.'):'Your collection request can be saved. Email notification is not connected yet; contact support@sieg.ltd to confirm collection.'))}
form.addEventListener('change',e=>{if(e.target.name==='delivery')update();if(e.target.name==='billingCountry')updateLocalPrice()});close.onclick=()=>{if(!busy)dialog.close()};dialog.addEventListener('cancel',e=>{if(busy)e.preventDefault()});

const adminToggle=dialog.querySelector('#rdAdmin'),adminPanel=dialog.querySelector('#rdAdminPanel'),masterPassword=dialog.querySelector('#rdMasterPassword'),adminDownload=dialog.querySelector('#rdAdminDownload');
adminToggle.onchange=()=>{adminPanel.hidden=!adminToggle.checked;masterPassword.value='';if(adminToggle.checked)masterPassword.focus()};
dialog.addEventListener('close',()=>{masterPassword.value='';adminToggle.checked=false;adminPanel.hidden=true});
adminDownload.onclick=async()=>{
 if(busy||!current)return;
 if(!masterPassword.value){showStatus('Enter your admin master password.');masterPassword.focus();return}
 busy=true;close.disabled=true;adminDownload.disabled=true;update();
 try{
  showStatus('Verifying admin access…');
  await api('admin-download',{password:masterPassword.value});masterPassword.value='';
  const contact={name:form.elements.name.value.trim()||'SIEG Admin',email:form.elements.email.value.trim()||'support@sieg.ltd',phone:form.elements.phone.value,dial:form.elements.dial.value,country:form.elements.billingCountry.selectedOptions[0].textContent,consent:true};
  showStatus('Preparing analysed-area files…');const prepared=await current.build(contact,current.selectedReports);
  if(!Array.isArray(prepared)||!prepared.length)throw Error('No completed report or download is available.');
  for(const f of prepared){
   let content=f.content;if(f.encoding==='base64'){const raw=atob(content);content=Uint8Array.from(raw,c=>c.charCodeAt(0))}
   const blob=new Blob([content],{type:f.type||'application/octet-stream'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=String(f.filename||'SIEG_Report.pdf').replace(/[^A-Za-z0-9_.-]/g,'_');document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);
  }
  showStatus('Admin verified. Download started. Check your browser downloads.');
 }catch(e){masterPassword.value='';showStatus(e.message)}finally{busy=false;close.disabled=false;adminDownload.disabled=false;update()}
};


const picker=document.createElement('dialog');picker.className='report-delivery rd-picker';picker.setAttribute('aria-labelledby','rdPickerTitle');picker.innerHTML='<button type="button" class="rd-close" aria-label="Close analysis selection">×</button><p class="rd-kicker">STEP 1 / REPORT CONTENTS</p><h2 id="rdPickerTitle">Choose analyses to include</h2><p class="rd-note">Select the items for this report. The displayed report fee covers this request.</p><div class="rd-picker-actions"><button type="button" data-all>Select all</button><button type="button" data-none>Clear selection</button></div><form><div class="rd-picker-list"></div><p class="rd-picker-status" role="status"></p><button type="submit" class="rd-submit">Next · collection & payment ↗</button></form>';document.body.append(picker);
let pickerOptions=null;const pickerForm=picker.querySelector('form'),pickerList=picker.querySelector('.rd-picker-list');
const defaultReportItems={fields:[['soil','Soil texture'],['suitability','Land Suitability'],['weather','Climate'],['recommendations','Suitable crops'],['monitoring','Crop monitoring'],['warning','Early Warning'],['yield','Yield estimation']],irrigation:[['summary','Design & water demand'],['layout','Irrigation layout map'],['assessment','Soil & terrain evidence'],['boq','Materials & labour BOQ']],estate:[['analysis','Accessibility findings'],['map','Area map']]};
function pickReports(options){pickerOptions=options;pickerList.replaceChildren();let items;try{items=typeof options.items==='function'?options.items():options.items||((defaultReportItems[options.service]||[['analysis','Current analysis']]).map(([id,label])=>({id,label})));}catch(e){items=[];picker.querySelector('.rd-picker-status').textContent=e.message}for(const item of items){const label=document.createElement('label'),input=document.createElement('input'),span=document.createElement('span');input.type='checkbox';input.name='analysis';input.value=item.id;input.disabled=!!item.disabled||(options.service==='fields'&&item.id==='yield'&&!window.SiegYield?.report?.());input.checked=!input.disabled&&(!options.selectedReports||options.selectedReports.includes(item.id));span.textContent=item.label;label.append(input,span);pickerList.append(label)}picker.showModal();syncPicker()}
function syncPicker(){const count=pickerList.querySelectorAll('input:checked:not(:disabled)').length;pickerForm.querySelector('[type=submit]').disabled=!count;picker.querySelector('.rd-picker-status').textContent=count?count+' item(s) selected.':'Select at least one available analysis. Complete an analysis first if no items are available.'}
picker.querySelector('.rd-close').onclick=()=>picker.close();pickerList.addEventListener('change',syncPicker);for(const [selector,checked]of [['[data-all]',true],['[data-none]',false]])picker.querySelector(selector).onclick=()=>{pickerList.querySelectorAll('input:not(:disabled)').forEach(i=>i.checked=checked);syncPicker()};
pickerForm.onsubmit=e=>{e.preventDefault();const selectedReports=[...pickerList.querySelectorAll('input:checked:not(:disabled)')].map(i=>i.value);if(!selectedReports.length)return;const options=pickerOptions;picker.close();open({...options,selectedReports})};
function filterSections(html,selected,mapping){if(!Array.isArray(selected))return html;const doc=new DOMParser().parseFromString(html,'text/html');let include=true;for(const el of [...doc.body.children]){if(el.tagName==='H2'){const id=mapping[el.textContent.trim()];include=!id||selected.includes(id)}if(!include)el.remove()}return '<!doctype html>'+doc.documentElement.outerHTML}

