const reportCache=new Map(),deliveredReports=new Map();
function reportCacheKey(options,selected){const a=window.SiegeUsage?.active;return JSON.stringify(['20261123-topic-quarter',a?.id,a?.geometryHash,a?.year,a?.task,options.version,options.service,window.SiegIndicatorSelection?.items(),[...selected].sort()]);}
function reportFilesCached(options,contact,selected){const key=reportCacheKey(options,selected);if(!reportCache.has(key))reportCache.set(key,Promise.resolve().then(()=>options.build(contact,selected)).then(pdfFiles).catch(error=>{reportCache.delete(key);throw error}));return reportCache.get(key);}
const computation=document.querySelector('.gee-computation-status');if(computation)new MutationObserver(()=>{if(!busy&&!window.SiegPreparingReport&&!reportLoads.size&&computation.dataset.state==='busy'){reportCache.clear();deliveredReports.clear();}}).observe(computation,{attributes:true,attributeFilter:['data-state']});
