function open(options){if(busy)return;if(!options.analysisPurchaseId&&['fields','eco','hydrology','irrigation','catchment','wetlands'].includes(options.service)){if(options.kind==='report'&&!options.selectedReports){pickReports(options);return;}deliverPaid(options).catch(e=>{const node=document.getElementById('usageStatus');if(node){node.hidden=false;node.textContent=e.message+' Retry delivery without paying again, or request refund review from your paid quote.';}});return;}if(options.kind==='report'&&!options.selectedReports){pickReports(options);return}editSelection.hidden=options.kind!=='report';const download=options.kind==='download';dialog.querySelector('.rd-kicker').textContent=download?'YOUR DOWNLOAD, YOUR WAY':'YOUR REPORT, YOUR WAY';dialog.querySelector('#rdTitle').textContent=download?'Choose how to receive your files':'Request '+(names[options.service]||'SIEG')+' Report';const collection=dialog.querySelector('.rd-choice');collection.querySelector('strong').textContent=download?'Collect files at SIEG':'Collect report at SIEG';collection.querySelector('small').textContent=download?'Your digital files are sent to SIEG. Pay cash before collecting them.':'We send your report to SIEG for printing. Collect it at our office and pay cash.';form.querySelectorAll('[name=delivery]').forEach(x=>x.disabled=false);dialog.querySelector('#rdFeeLabel').textContent=options.kind==='download'?'Download fee':'Report fee';current=options;let review=dialog.querySelector('#rdReportReview');if(!review){review=document.createElement('div');review.id='rdReportReview';form.prepend(review);}review.replaceChildren();if(options.quote?.reportItems){const h=document.createElement('strong');h.textContent='Your report includes';const ul=document.createElement('ul');for(const id of options.quote.reportItems){const li=document.createElement('li');li.textContent=((options.service==='eco'?window.SiegEcoSelection?.labels[id]:options.service==='fields'?window.SiegFieldsSelection?.labels[id]:window.SiegeUsage?.reportLabels?.[id])||id)+(id==='yield'?' — requires your harvest records before report delivery':'');ul.append(li);}const label=document.createElement('label'),check=document.createElement('input');check.type='checkbox';check.name='confirmReportItems';check.required=true;label.append(check,document.createTextNode(options.service==='fields'?'I confirm these report items. Crop and vegetable recommendations appear last.':'I confirm these report items.'));review.append(h,ul,label);}files=null;completed=false;requestId=crypto.randomUUID?.()||Array.from(crypto.getRandomValues(new Uint8Array(16)),b=>b.toString(16).padStart(2,'0')).join('');config=null;form.reset();const paidMapping=!!options.analysisPurchaseId||['catchment','wetlands'].includes(options.service);collection.hidden=paidMapping;if(paidMapping){form.elements.delivery.value='card';form.querySelector('[name=delivery][value=collection]').disabled=true;}adminPanel.hidden=true;masterPassword.value='';defaultBillingCountry();fxVersion++;dialog.querySelector('#rdLocalPrice').textContent='';dialog.querySelector('#rdRateNote').textContent='';showStatus('');dialog.querySelector('#rdService').textContent=options.analysisPurchaseId?((options.title||names[options.service])+' · '+options.quote.areaKm2.toFixed(2)+' km² · '+options.quote.year+' · Payment unlocks the confirmed report items for this area. Files are prepared after payment.'):(names[options.service]+' · Files cover the completed analysis area only.');if(options.analysisPurchaseId){dialog.querySelector('#rdTitle').textContent='Confirm service & pay';dialog.querySelector('#rdFeeLabel').textContent='Analysis and delivery fee';editSelection.hidden=true;}dialog.querySelector('#rdPrice').textContent='Loading…';dialog.showModal();update();api('config').then(d=>{config=d;if(d.profile?.code)form.elements.billingCountry.value=d.profile.code;dialog.querySelector('#rdPrice').textContent=!['catchment','wetlands'].includes(options.service)&&window.SiegeUsage?.active?.policyVersion===1?'Included in authorised analysis':d.currency+' '+(d.prices[options.service]/100).toFixed(2);update();updateLocalPrice()}).catch(e=>showStatus(e.message))}
let pdfToolsReady;
async function pdfReport(html){if(!window.SiegReportPDF?.convert){if(!pdfToolsReady)pdfToolsReady=new Promise((resolve,reject)=>{const tag=document.createElement('script'),timer=setTimeout(()=>reject(Error('PDF tools took too long to load. Retry without paying again.')),30000);tag.src=new URL('report-pdf.js?v=20261123-topic-quarter',style.href).href;tag.onload=()=>{clearTimeout(timer);window.SiegReportPDF?.convert?resolve():reject(Error('PDF tools could not start.'))};tag.onerror=()=>{clearTimeout(timer);reject(Error('PDF tools could not load. Retry without paying again.'))};document.head.append(tag);}).catch(error=>{pdfToolsReady=null;throw error});await pdfToolsReady;}if(window.SiegeReportKit?.alignReportPages)html=window.SiegeReportKit.alignReportPages(html);return window.SiegReportPDF.convert(html,{onProgress:reportNotice});}
async function pdfFiles(files){return Promise.all(files.map(async f=>f.type==='text/html'?file(f.encoding==='base64'?new TextDecoder().decode(Uint8Array.from(atob(f.content),c=>c.charCodeAt(0))):f.content,f.filename):f));}
async function file(content,filename,type='text/html',encoding='utf8'){
 let reportMetadata,reservation;
 if(/\.html?$/i.test(filename)||type==='text/html'){let html=content instanceof Blob?await content.text():String(content);const doc=new DOMParser().parseFromString(html,'text/html'),active=window.SiegeUsage?.active;const signature=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(html))),b=>b.toString(16).padStart(2,'0')).join('');const service=active?.service||current?.service||[...registeredReports.keys()][0]||(/estate/.test(location.pathname)?'estate':'address');reservation=await api('references/reserve',{service,analysisId:active?.id,year:active?.year,geometry:active?.geometry||JSON.parse(doc.querySelector('meta[name="sieg-analysed-boundary"]')?.content||'null'),signature});for(const target of [doc.querySelector('.report-title'),doc.querySelector('.report-content')||doc.body]){if(!target)continue;const label=doc.createElement('p');label.textContent='Report reference: '+reservation.reference;label.style.cssText='font-size:9px;line-height:1.5;color:#176f73;overflow-wrap:anywhere;word-break:break-all';target.prepend(label);}html='<!doctype html>'+doc.documentElement.outerHTML;reportMetadata={reference:reservation.reference,indicatorSelections:window.SiegIndicatorSelection?.items(),version:html.match(/data-report-version="([^"]+)"/)?.[1],services:[...html.matchAll(/data-service="([^"]+)"/g)].map(m=>m[1])};content=await pdfReport(html);filename=filename.replace(/\.(?:pdf|html?)$/i,'.pdf');if(!/\.pdf$/i.test(filename))filename+='.pdf';type='application/pdf';encoding='base64';}
 filename=filename.replace(/[^A-Za-z0-9_.-]/g,'_').slice(-100);
 if(content instanceof Blob){if(content.size>20*1024*1024&&!window.SiegeUsage?.active?.adminUnrestricted)throw Error('File exceeds the 20 MB report delivery limit.');const bytes=new Uint8Array(await content.arrayBuffer());let raw='';for(let i=0;i<bytes.length;i+=8192)raw+=String.fromCharCode(...bytes.subarray(i,i+8192));const prepared={filename,type,encoding:'base64',content:btoa(raw),reportTemplateVersion:'20261123-topic-quarter',...(reportMetadata?{reportMetadata}:{})};if(reservation){prepared.reportReference=reservation.reference;await api('references/complete',{reference:reservation.reference});return prepared;}return prepared;}
 return {filename,type,encoding,content:String(content)};
}
form.onsubmit=async e=>{e.preventDefault();if(busy||completed||!config)return;const method=form.elements.delivery.value;if(method==='card'&&!config.cardEnabled&&!window.SiegeUsage?.active?.paymentVerified)return;busy=true;close.disabled=true;update();try{const contact=Object.fromEntries(new FormData(form));contact.country=form.elements.billingCountry.selectedOptions[0].textContent;if(current.selectedReports)contact.selectedAnalyses=current.selectedReports.join(', ');showStatus(current.analysisPurchaseId?'Confirming your quoted area and service…':'Preparing your analysed-area files…');if(!current.analysisPurchaseId&&!files)files=await current.build(contact,current.selectedReports);if(!current.analysisPurchaseId&&(!Array.isArray(files)||!files.length))throw Error('No analysed report or download is available.');showStatus(method==='card'?'Creating your secure checkout…':current.kind==='download'?'Submitting your files to SIEG…':'Submitting your report to SIEG…');const d=await api('orders',{service:current.service,kind:current.kind,method,contact,files,analysisPurchaseId:current.analysisPurchaseId,reportItems:current.quote?.reportItems,confirmReportItems:form.elements.confirmReportItems?.checked===true,requestId,expectedAmount:config.prices[current.service],analysisId:window.SiegeUsage?.active?.id});current.onSubmitted?.(d);if(d.alreadyPaid){completed=true;showStatus(d.message||'This analysis is already paid. Resume it from Saved analyses.');return;}if(d.checkout){if(d.checkout.url!=='https://secure.paygate.co.za/payweb3/process.trans')throw Error('Unexpected payment provider.');const f=document.createElement('form');f.method='POST';f.action=d.checkout.url;f.target='_top';for(const [name,value]of Object.entries(d.checkout.fields)){const input=document.createElement('input');input.type='hidden';input.name=name;input.value=value;f.append(input)}document.body.append(f);showStatus('Opening secure Visa checkout…');completed=true;f.submit()}else{completed=true;showStatus((d.message||'Request saved.')+'\nReference: '+d.id+'\nFee: '+d.currency+' '+(d.amount/100).toFixed(2));files=null}}catch(err){showStatus(err.message)}finally{busy=false;close.disabled=false;update()}};
